let model;const $=id=>document.getElementById(id);const pct=x=>(x*100).toFixed(1)+'%';function matrix(rows,t){return rows.reduce((a,r)=>{a[r.y?(r.score>=t?'tp':'fn'):(r.score>=t?'fp':'tn')]++;return a},{tp:0,fn:0,fp:0,tn:0})}function render(){const t=+$('threshold').value/100,c=matrix(model.test,t);$('thresholdLabel').textContent=t.toFixed(2);for(const k of ['tp','fn','fp'])$(k).textContent=c[k];$('sensitivity').textContent=`${pct(c.tp/67)} of 67 positive cases`;$('fnrate').textContent=`${pct(c.fn/67)} of 67 positive cases`;$('fprate').textContent=`${pct(c.fp/125)} of 125 negative cases`;$('catchbar').style.width=pct(c.tp/67);$('missbar').style.width=pct(c.fn/67);$('alarmbar').style.width=pct(c.fp/125);$('accuracy').textContent=pct((c.tp+c.tn)/192);$('tablefn').textContent=c.fn;$('tablefp').textContent=c.fp;const delta=100*((c.tp+c.tn)-125)/192;$('comparison').textContent=`At threshold ${t.toFixed(2)}, accuracy is ${Math.abs(delta).toFixed(1)} percentage points ${delta>=0?'above':'below'} the baseline. ${c.tp+c.fp} records are flagged for review.`;$('auc').textContent=model.auc.toFixed(3);$('groups').innerHTML=[['Ages 21–39',r=>r.x[3]<40],['Ages 40+',r=>r.x[3]>=40]].map(([name,filter])=>{const rows=model.test.filter(filter),v=matrix(rows,t);return `<div class="group"><span>${name}<br><small>${rows.length} test records</small></span><strong>${v.fn} / ${v.tp+v.fn} positives missed<br>${pct(v.fn/(v.tp+v.fn))} false-negative rate</strong></div>`}).join('');renderCase()}function renderCase(){const r=model.test.find(r=>r.id===$('case').value),t=+$('threshold').value/100,flag=r.score>=t;const labels=[['Glucose','mg/dL'],['Diastolic BP','mm Hg'],['BMI','kg/m²'],['Age','years']];$('measurements').innerHTML=labels.map(([name,unit],i)=>`<div><small>${name}</small><strong>${r.x[i]??'Missing'}</strong><span>${unit}</span></div>`).join('');let z=model.intercept;for(let i=0;i<4;i++)z+=((r.x[i]??model.median[i])-model.mean[i])/model.scale[i]*model.coef[i];$('score').textContent=pct(1/(1+Math.exp(-z)));$('decision').textContent=flag?'Flagged for review':'Below the flag threshold';const outcome=r.y?(flag?'True positive':'False negative · missed case'):(flag?'False positive · false alarm':'True negative');$('truth').textContent=`Dataset label: ${r.y?'positive':'negative'} · ${outcome}`;$('explanation').textContent=flag!==Boolean(r.y)?'A real model error. The four input measurements overlap between positive and negative cases. Missing data and unmeasured health factors may contribute, but this record cannot establish why the prediction is wrong.':'The prediction matches this dataset label. This is not proof of an individual’s health status; a below-threshold score cannot rule out diabetes.'}fetch('model.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(m=>{model=m;$('case').innerHTML=model.test.map(r=>`<option value="${r.id}">${r.id} · public test record</option>`).join('');const err=m.test.find(r=>r.y===1&&r.score<.35);$('case').value=err.id;render();$('threshold').oninput=render;$('case').onchange=renderCase;$('wrong').onclick=()=>{const t=+$('threshold').value/100;const r=model.test.find(r=>Boolean(r.y)!==(r.score>=t));if(r){$('case').value=r.id;renderCase()}}}).catch(()=>{$('decision').textContent='Model could not load. Refresh to try again.'});
